with filtered_orders as (select *, trim(status) clean_status from orders where customer_id in (15, 16, 19) and discount between 0.23 and 0.26 and discount > 0.18), agg as (select case when year(order_date) < 2024 then 'before_2024' when year(order_date) = 2024 then '2024' else 'after_2024' end order_cohort, max(order_date) latest_order_date from filtered_orders group by case when year(order_date) < 2024 then 'before_2024' when year(order_date) = 2024 then '2024' else 'after_2024' end) select order_cohort, latest_order_date from agg order by order_cohort desc
